-- Shared workflow schema mirrored from the compact baseline.
CREATE TABLE IF NOT EXISTS workflow_instance (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    workflow_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    kind VARCHAR(48) COLLATE utf8mb4_bin NOT NULL,
    idempotency_scope VARCHAR(160) COLLATE utf8mb4_bin NOT NULL,
    request_id VARCHAR(128) COLLATE utf8mb4_bin NOT NULL,
    request_sha256 CHAR(64) COLLATE utf8mb4_bin NOT NULL,
    owner_user_id BIGINT NOT NULL,
    actor_user_id BIGINT NULL,
    parent_workflow_id BIGINT UNSIGNED NULL,
    resource_type VARCHAR(32) COLLATE utf8mb4_bin NULL,
    resource_id VARCHAR(180) COLLATE utf8mb4_bin NULL,
    resource_revision BIGINT NULL,
    requested_tokens BIGINT NULL,
    decider_user_id BIGINT NULL,
    session_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    run_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    status VARCHAR(32) COLLATE utf8mb4_bin NOT NULL,
    revision BIGINT NOT NULL DEFAULT 0,
    fence BIGINT NOT NULL DEFAULT 0,
    active_slot TINYINT NULL,
    claim_token VARCHAR(64) COLLATE utf8mb4_bin NULL,
    lease_expires_at DATETIME(6) NULL,
    attempts INT NOT NULL DEFAULT 0,
    effective_date DATE NULL,
    scheduled_for DATETIME(6) NULL,
    error_code VARCHAR(80) COLLATE utf8mb4_bin NULL,
    next_attempt_at DATETIME(6) NULL,
    expires_at DATETIME(6) NULL,
    execution_state VARCHAR(32) COLLATE utf8mb4_bin NULL,
    reserved_bytes BIGINT NULL,
    exit_verified BOOLEAN NULL,
    execution_deadline DATETIME(6) NULL,
    payload_version SMALLINT NOT NULL,
    payload_json LONGTEXT NOT NULL,
    result_version SMALLINT NULL,
    result_json LONGTEXT NULL,
    result_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),
    updated_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),
    finished_at DATETIME(6) NULL,
    legacy_source VARCHAR(64) COLLATE utf8mb4_bin NULL,
    legacy_key VARCHAR(512) COLLATE utf8mb4_bin NULL,
    knowledge_request_id VARCHAR(128) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='KNOWLEDGE_COMMAND' THEN request_id ELSE NULL END) VIRTUAL,
    fork_result_key VARCHAR(128) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='WORKSPACE_FORK' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.resultSessionId')) ELSE NULL END) VIRTUAL,
    report_request_id VARCHAR(128) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS
        (CASE WHEN kind IN ('REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN') THEN request_id ELSE NULL END) VIRTUAL,
    report_consumed_id VARCHAR(180) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS
        (CASE WHEN kind='REPORT_CONSUMPTION' THEN resource_id ELSE NULL END) VIRTUAL,
    model_probe_id VARCHAR(160) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_JSON_PROBE' THEN JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.modelId')) ELSE NULL END) VIRTUAL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_workflow_external (workflow_id),
    UNIQUE KEY uk_workflow_request (kind,idempotency_scope,request_id),
    UNIQUE KEY uk_workflow_knowledge_request (idempotency_scope,knowledge_request_id),
    UNIQUE KEY uk_workflow_active_input (kind,owner_user_id,session_id,active_slot),
    UNIQUE KEY uk_workflow_fork_result (fork_result_key),
    UNIQUE KEY uk_workflow_report_request (kind,idempotency_scope,report_request_id),
    UNIQUE KEY uk_workflow_report_consumption (report_consumed_id,resource_revision),
    UNIQUE KEY uk_workflow_legacy (legacy_source,legacy_key),
    KEY ix_workflow_owner (kind,owner_user_id,status,id),
    KEY ix_workflow_dispatch_owner (kind,status,owner_user_id,id),
    KEY ix_workflow_session (kind,owner_user_id,session_id,id),
    KEY ix_workflow_run (kind,owner_user_id,run_id,status,id),
    KEY ix_workflow_ready (kind,status,next_attempt_at,id),
    KEY ix_workflow_lease (kind,status,lease_expires_at,id),
    KEY ix_workflow_expiry (kind,status,expires_at,id),
    KEY ix_workflow_resource (kind,resource_type,resource_id,id),
    KEY ix_workflow_parent (parent_workflow_id,id),
    KEY ix_workflow_model_probe (kind,resource_revision,model_probe_id,status),
    KEY ix_workflow_execution (kind,execution_state,execution_deadline),
    CONSTRAINT fk_workflow_parent FOREIGN KEY(parent_workflow_id) REFERENCES workflow_instance(id),
    CONSTRAINT ck_workflow_kind CHECK (kind IN ('CONVERSATION_INPUT','KNOWLEDGE_COMMAND','WORKSPACE_FORK','DIGEST_RUN','DIGEST_COMMAND','LLM_REQUEST','LLM_PROVIDER_ATTEMPT','REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN','MODEL_CONFIG_COMMAND','MODEL_JSON_PROBE','SKILL_IMPORT_COMMAND','SKILL_DOWNLOAD','SKILL_STORAGE_COMMAND','MEMORY_MUTATION','LLM_QUOTA_CHANGE','LLM_QUOTA_APPLICATION')),
    CONSTRAINT ck_workflow_owner CHECK (owner_user_id>0 AND (actor_user_id IS NULL OR actor_user_id>0)),
    CONSTRAINT ck_workflow_versions CHECK (revision>=0 AND fence>=0 AND attempts>=0 AND payload_version>0),
    CONSTRAINT ck_workflow_payload CHECK (JSON_VALID(payload_json)),
    CONSTRAINT ck_workflow_result CHECK ((result_json IS NULL AND result_version IS NULL AND result_sha256 IS NULL) OR (result_json IS NOT NULL AND result_version IS NOT NULL AND result_version>0 AND result_sha256 IS NOT NULL AND JSON_VALID(result_json))),
    CONSTRAINT ck_workflow_claim CHECK ((claim_token IS NULL AND lease_expires_at IS NULL) OR (claim_token IS NOT NULL AND lease_expires_at IS NOT NULL AND fence>0)),
    CONSTRAINT ck_workflow_legacy CHECK ((legacy_source IS NULL AND legacy_key IS NULL) OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL)),
    CONSTRAINT ck_workflow_input CHECK (kind<>'CONVERSATION_INPUT' OR (session_id IS NOT NULL AND expires_at IS NOT NULL AND payload_version=1
        AND status IN ('QUEUED','STARTED','APPLIED','COMPLETED','CANCELLED','FAILED','EXPIRED')
        AND ((status='STARTED' AND active_slot IS NOT NULL AND active_slot=1 AND claim_token IS NOT NULL) OR (status<>'STARTED' AND active_slot IS NULL)))),
    CONSTRAINT ck_workflow_knowledge_request CHECK (kind<>'KNOWLEDGE_COMMAND' OR CHAR_LENGTH(request_id)<=64),
    CONSTRAINT ck_workflow_other_slot CHECK (kind='CONVERSATION_INPUT' OR active_slot IS NULL),
    CONSTRAINT ck_workflow_receipt CHECK (kind NOT IN ('KNOWLEDGE_COMMAND','WORKSPACE_FORK','DIGEST_COMMAND','REPORT_COMMAND','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN','MODEL_CONFIG_COMMAND','SKILL_IMPORT_COMMAND','LLM_QUOTA_CHANGE') OR (status='COMPLETED' AND finished_at IS NOT NULL AND claim_token IS NULL)),
    CONSTRAINT ck_workflow_quota_resource CHECK (kind NOT IN ('LLM_QUOTA_CHANGE','LLM_QUOTA_APPLICATION') OR (resource_type IS NOT NULL AND resource_type='LLM_MODEL' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 180 AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND payload_version=1)),
    CONSTRAINT ck_workflow_quota_application CHECK ((kind='LLM_QUOTA_APPLICATION' AND requested_tokens IS NOT NULL AND requested_tokens>0 AND status IN ('PENDING','APPROVED','REJECTED','CANCELLED') AND ((status='PENDING' AND decider_user_id IS NULL AND finished_at IS NULL) OR (status IN ('APPROVED','REJECTED') AND decider_user_id IS NOT NULL AND decider_user_id>0 AND finished_at IS NOT NULL) OR (status='CANCELLED' AND decider_user_id IS NOT NULL AND decider_user_id=owner_user_id AND finished_at IS NOT NULL))) OR (kind<>'LLM_QUOTA_APPLICATION' AND requested_tokens IS NULL AND decider_user_id IS NULL)),
    CONSTRAINT ck_workflow_skill_import CHECK (kind<>'SKILL_IMPORT_COMMAND' OR (resource_type IS NOT NULL AND resource_type='SKILL_IMPORT' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision=1 AND actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND expires_at IS NULL)),
    CONSTRAINT ck_workflow_skill_download CHECK (kind<>'SKILL_DOWNLOAD' OR (resource_type IS NOT NULL AND resource_type='SKILL_DOWNLOAD' AND resource_id IS NOT NULL AND resource_id=workflow_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id)<=64 AND status IN ('DOWNLOADING','DOWNLOADED','DRAFT_CREATED','NO_CHANGE','ERROR','NEEDS_REVIEW','PURGING','PURGED','CLEANUP_ERROR') AND ((status='PURGED' AND finished_at IS NOT NULL AND claim_token IS NULL) OR (status<>'PURGED' AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_execution CHECK ((execution_state IS NULL AND reserved_bytes IS NULL AND exit_verified IS NULL AND execution_deadline IS NULL) OR (kind='SKILL_DOWNLOAD' AND execution_state IS NOT NULL AND execution_state IN ('RESERVED','RUNNING','SEALED','RELEASED','NEEDS_REVIEW') AND reserved_bytes IS NOT NULL AND reserved_bytes>=0 AND exit_verified IS NOT NULL AND execution_deadline IS NOT NULL AND ((execution_state IN ('SEALED','RELEASED') AND exit_verified=TRUE AND reserved_bytes=0) OR (execution_state IN ('RESERVED','RUNNING','NEEDS_REVIEW') AND exit_verified=FALSE)))),
    CONSTRAINT ck_workflow_skill_storage CHECK (kind<>'SKILL_STORAGE_COMMAND' OR (resource_type IS NOT NULL AND resource_type='SKILL_DOWNLOAD' AND resource_id IS NOT NULL AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id)<=64 AND expires_at IS NULL AND claim_token IS NULL AND status IN ('STARTED','COMPLETED','ERROR') AND ((status='STARTED' AND finished_at IS NULL) OR (status IN ('COMPLETED','ERROR') AND finished_at IS NOT NULL)))),
    CONSTRAINT ck_workflow_memory_mutation CHECK (kind<>'MEMORY_MUTATION' OR (resource_type IS NOT NULL AND resource_type='MEMORY' AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND CHAR_LENGTH(request_id) BETWEEN 1 AND 64 AND request_sha256 REGEXP '^[a-f0-9]{64}$' AND payload_version=1 AND JSON_LENGTH(payload_json)=1 AND JSON_EXTRACT(payload_json,'$.action') IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action')) IN ('DELETE','UPDATE','AUTOSAVE','REVIEW_DECISION','LIFECYCLE') AND ((JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action'))='AUTOSAVE' AND resource_id IS NULL) OR (JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.action'))<>'AUTOSAVE' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 64)) AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND effective_date IS NULL AND scheduled_for IS NULL AND result_json IS NULL AND status IN ('PENDING','DISPATCHED','SUCCEEDED','REJECTED','UNKNOWN') AND ((status IN ('SUCCEEDED','REJECTED') AND finished_at IS NOT NULL) OR (status IN ('PENDING','DISPATCHED','UNKNOWN') AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_model_config CHECK (kind NOT IN ('MODEL_CONFIG_COMMAND','MODEL_JSON_PROBE') OR (resource_type IS NOT NULL AND resource_type='LLM_CONFIGURATION' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision>0 AND resource_id=CAST(resource_revision AS CHAR))),
    CONSTRAINT ck_workflow_model_command CHECK (kind<>'MODEL_CONFIG_COMMAND' OR (actor_user_id IS NOT NULL AND actor_user_id=owner_user_id AND idempotency_scope=CONCAT('OWNER:',owner_user_id) AND expires_at IS NULL AND payload_version=1)),
    CONSTRAINT ck_workflow_model_probe CHECK (kind<>'MODEL_JSON_PROBE' OR (model_probe_id IS NOT NULL AND CHAR_LENGTH(model_probe_id) BETWEEN 1 AND 160 AND idempotency_scope=CONCAT('MODEL_CONFIG:',resource_revision) AND payload_version=1 AND status IN ('STARTED','PASSED','FAILED') AND parent_workflow_id IS NULL AND session_id IS NULL AND run_id IS NULL AND claim_token IS NULL AND expires_at IS NULL AND ((status='STARTED' AND finished_at IS NULL) OR (status IN ('PASSED','FAILED') AND (finished_at IS NOT NULL OR (legacy_source IS NOT NULL AND legacy_source='agent_model_json_probe' AND legacy_key IS NOT NULL)))))),
    CONSTRAINT ck_workflow_report CHECK (kind NOT IN ('REPORT_COMMAND','REPORT_CONFIRMATION','REPORT_DELIVERY','REPORT_CONSUMPTION','REPORT_AGENT_ORIGIN') OR (resource_type IS NOT NULL AND resource_type='QUALITY_REPORT' AND resource_id IS NOT NULL AND resource_revision IS NOT NULL AND resource_revision>=0)),
    CONSTRAINT ck_workflow_report_confirmation CHECK (kind<>'REPORT_CONFIRMATION' OR (expires_at IS NOT NULL AND CHAR_LENGTH(request_id)<=64 AND idempotency_scope='REPORT_CONFIRMATION' AND status IN ('PENDING','USED','EXPIRED') AND claim_token IS NULL AND ((status='PENDING' AND finished_at IS NULL) OR (status<>'PENDING' AND finished_at IS NOT NULL)))),
    CONSTRAINT ck_workflow_report_delivery CHECK (kind<>'REPORT_DELIVERY' OR (status IN ('PENDING','RETRY','PROCESSING','DELIVERED','FAILED') AND ((status='PROCESSING' AND claim_token IS NOT NULL) OR (status<>'PROCESSING' AND claim_token IS NULL)) AND ((status='DELIVERED' AND finished_at IS NOT NULL) OR (status<>'DELIVERED' AND finished_at IS NULL)))),
    CONSTRAINT ck_workflow_digest CHECK (kind<>'DIGEST_RUN' OR status IN ('PENDING','RUNNING','COMPLETED','FAILED','BLOCKED')),
    CONSTRAINT ck_workflow_llm_request CHECK (kind<>'LLM_REQUEST' OR status IN ('OPEN','SETTLING','COMPLETED','NEEDS_REVIEW','CANCELLED')),
    CONSTRAINT ck_workflow_llm_attempt CHECK (kind<>'LLM_PROVIDER_ATTEMPT' OR (parent_workflow_id IS NOT NULL AND status IN ('RESERVED','STARTED','COMPLETED','FAILED','CANCELLED','NEEDS_REVIEW')))
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS scheduled_plan (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    plan_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    kind VARCHAR(48) COLLATE utf8mb4_bin NOT NULL,
    owner_user_id BIGINT NOT NULL,
    owner_name VARCHAR(128) COLLATE utf8mb4_bin NOT NULL,
    name VARCHAR(160) NOT NULL,
    cron_expression VARCHAR(128) COLLATE utf8mb4_bin NOT NULL,
    time_zone VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    enabled BOOLEAN NOT NULL,
    revision BIGINT NOT NULL DEFAULT 0,
    next_fire_at DATETIME(6) NULL,
    payload_version SMALLINT NOT NULL,
    payload_json LONGTEXT NOT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),
    updated_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),
    PRIMARY KEY (id),
    UNIQUE KEY uk_scheduled_plan_external (plan_id),
    KEY ix_scheduled_plan_due (kind,enabled,next_fire_at,id),
    KEY ix_scheduled_plan_owner (kind,owner_user_id,id),
    CONSTRAINT ck_scheduled_plan_kind CHECK (kind='DIGEST_SCHEDULE'),
    CONSTRAINT ck_scheduled_plan_owner CHECK (owner_user_id>0 AND revision>=0),
    CONSTRAINT ck_scheduled_plan_payload CHECK (payload_version=1 AND JSON_VALID(payload_json)),
    CONSTRAINT ck_scheduled_plan_due CHECK (enabled=FALSE OR next_fire_at IS NOT NULL)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS audit_event (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    event_id VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    kind VARCHAR(48) COLLATE utf8mb4_bin NOT NULL,
    owner_user_id BIGINT NULL,
    actor_user_id BIGINT NULL,
    resource_type VARCHAR(32) COLLATE utf8mb4_bin NULL,
    resource_id VARCHAR(180) COLLATE utf8mb4_bin NULL,
    session_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    message_id BIGINT NULL,
    run_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    journal_run_id VARCHAR(36) COLLATE utf8mb4_bin NULL,
    research_export_run_id VARCHAR(36) COLLATE utf8mb4_bin GENERATED ALWAYS AS
        (CASE WHEN kind='RESEARCH_EXPORT' THEN run_id ELSE NULL END) STORED,
    sequence_no BIGINT NULL,
    request_id VARCHAR(128) COLLATE utf8mb4_bin NULL,
    action VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,
    revision BIGINT NULL,
    content_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    previous_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    event_sha256 CHAR(64) COLLATE utf8mb4_bin NULL,
    quantity BIGINT NULL,
    unit VARCHAR(16) COLLATE utf8mb4_bin NULL,
    request_scope VARCHAR(160) COLLATE utf8mb4_bin NULL,
    policy_version VARCHAR(64) COLLATE utf8mb4_bin NULL,
    outcome VARCHAR(32) COLLATE utf8mb4_bin NULL,
    observed_at DATETIME(6) NULL,
    observation_model_id VARCHAR(180) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_QUOTA_OBSERVATION' THEN resource_id ELSE NULL END) VIRTUAL,
    observation_request_id VARCHAR(64) COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS
        (CASE WHEN kind='MODEL_QUOTA_OBSERVATION' THEN request_id ELSE NULL END) VIRTUAL,
    occurred_at DATETIME(6) NOT NULL DEFAULT (UTC_TIMESTAMP(6)),
    payload_version SMALLINT NOT NULL,
    payload_json LONGTEXT NOT NULL,
    legacy_source VARCHAR(64) COLLATE utf8mb4_bin NULL,
    legacy_key VARCHAR(512) COLLATE utf8mb4_bin NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_audit_event_external (event_id),
    UNIQUE KEY uk_audit_event_request_identity (kind,request_scope,request_id),
    UNIQUE KEY uk_audit_event_sequence (kind,run_id,sequence_no),
    UNIQUE KEY uk_audit_event_message (kind,owner_user_id,session_id,message_id),
    UNIQUE KEY uk_audit_event_legacy (legacy_source,legacy_key),
    UNIQUE KEY uk_audit_observation_request (request_scope,observation_request_id),
    KEY ix_audit_event_owner (kind,owner_user_id,id),
    KEY ix_audit_event_actor (kind,actor_user_id,id),
    KEY ix_audit_event_resource (kind,resource_type,resource_id,id),
    KEY ix_audit_event_request (kind,request_id,id),
    KEY ix_audit_event_time (kind,occurred_at,id),
    KEY ix_audit_evaluation (kind,resource_id,revision,policy_version,outcome,id),
    KEY ix_audit_journal_owner (owner_user_id,journal_run_id),
    KEY ix_audit_research_export (kind,owner_user_id,run_id,id),
    KEY ix_audit_export_run_owner (owner_user_id,research_export_run_id),
    KEY ix_audit_observation (kind,observation_model_id,observed_at,id),
    CONSTRAINT ck_audit_journal CHECK ((kind='AGENT_RUN' AND owner_user_id IS NOT NULL AND journal_run_id IS NOT NULL AND run_id IS NOT NULL AND journal_run_id=run_id AND sequence_no IS NOT NULL AND sequence_no>0 AND payload_version=1) OR (kind<>'AGENT_RUN' AND journal_run_id IS NULL)),
    CONSTRAINT ck_audit_event_quantity CHECK ((quantity IS NULL AND unit IS NULL) OR (quantity IS NOT NULL AND unit IS NOT NULL AND quantity>=0)),
    CONSTRAINT ck_audit_observation CHECK ((kind='MODEL_QUOTA_OBSERVATION' AND owner_user_id IS NOT NULL AND actor_user_id IS NOT NULL AND owner_user_id=actor_user_id AND resource_type IS NOT NULL AND resource_type='LLM_MODEL' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id)>0 AND quantity IS NOT NULL AND unit IS NOT NULL AND unit='TOKENS' AND request_scope IS NOT NULL AND request_scope=CONCAT('OWNER:',actor_user_id) AND request_id IS NOT NULL AND CHAR_LENGTH(request_id) BETWEEN 1 AND 64 AND content_sha256 IS NOT NULL AND observed_at IS NOT NULL) OR (kind<>'MODEL_QUOTA_OBSERVATION' AND observed_at IS NULL)),
    CONSTRAINT ck_audit_evaluation CHECK (kind<>'SKILL_EVALUATION' OR (resource_type IS NOT NULL AND resource_type='SKILL' AND resource_id IS NOT NULL AND revision IS NOT NULL AND content_sha256 IS NOT NULL AND policy_version IS NOT NULL AND outcome IS NOT NULL AND outcome IN ('PASSED','FAILED'))),
    CONSTRAINT ck_audit_skill_source CHECK (kind<>'SKILL_SOURCE_GRANT' OR (owner_user_id IS NOT NULL AND actor_user_id IS NOT NULL AND owner_user_id=actor_user_id AND resource_type IS NOT NULL AND resource_type='AGENT_RUN' AND run_id IS NOT NULL AND resource_id IS NOT NULL AND resource_id=run_id AND request_id IS NOT NULL AND request_id=run_id AND content_sha256 IS NOT NULL AND request_scope IS NOT NULL AND request_scope=CONCAT('OWNER:',owner_user_id) AND payload_version=1)),
    CONSTRAINT ck_audit_research_export CHECK (kind<>'RESEARCH_EXPORT' OR (owner_user_id IS NOT NULL AND actor_user_id IS NOT NULL AND owner_user_id=actor_user_id AND resource_type IS NOT NULL AND resource_type='RESEARCH_EXPORT' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 36 AND request_id IS NOT NULL AND request_id=resource_id AND request_scope IS NOT NULL AND request_scope='RESEARCH_EXPORT' AND run_id IS NOT NULL AND CHAR_LENGTH(run_id) BETWEEN 1 AND 36 AND content_sha256 IS NOT NULL AND quantity IS NOT NULL AND unit IS NOT NULL AND unit='BYTES' AND payload_version=1)),
    CONSTRAINT ck_audit_memory_preference CHECK (kind<>'MEMORY_PREFERENCE' OR (owner_user_id IS NOT NULL AND resource_type IS NOT NULL AND resource_type='MEMORY_PREFERENCE' AND resource_id IS NOT NULL AND resource_id=CAST(owner_user_id AS CHAR) AND revision IS NOT NULL AND action='PREFERENCE_CHANGED' AND outcome IS NOT NULL AND outcome='SUCCEEDED' AND request_id IS NULL AND request_scope IS NULL AND payload_version=1 AND JSON_EXTRACT(payload_json,'$.readEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.readEnabled'))='BOOLEAN' AND JSON_EXTRACT(payload_json,'$.saveEnabled') IS NOT NULL AND JSON_TYPE(JSON_EXTRACT(payload_json,'$.saveEnabled'))='BOOLEAN')),
    CONSTRAINT ck_audit_memory_operation CHECK (kind<>'MEMORY_OPERATION' OR (owner_user_id IS NOT NULL AND resource_type IS NOT NULL AND resource_type='MEMORY_MUTATION' AND resource_id IS NOT NULL AND CHAR_LENGTH(resource_id) BETWEEN 1 AND 64 AND revision IS NOT NULL AND action IN ('DELETE','UPDATE','AUTOSAVE','REVIEW_DECISION','LIFECYCLE') AND outcome IS NOT NULL AND outcome IN ('PENDING','DISPATCHED','UNKNOWN','SUCCEEDED','REJECTED') AND request_id IS NOT NULL AND CHAR_LENGTH(request_id) BETWEEN 1 AND 64 AND request_scope IS NULL AND payload_version=1)),
    CONSTRAINT ck_audit_event_owner CHECK ((owner_user_id IS NULL OR owner_user_id>0) AND (actor_user_id IS NULL OR actor_user_id>0)),
    CONSTRAINT ck_audit_event_payload CHECK (payload_version>0 AND JSON_VALID(payload_json)),
    CONSTRAINT ck_audit_event_revision CHECK (revision IS NULL OR revision>=0),
    CONSTRAINT ck_audit_event_sequence CHECK (sequence_no IS NULL OR (run_id IS NOT NULL AND sequence_no>=0)),
    CONSTRAINT ck_audit_event_legacy CHECK ((legacy_source IS NULL AND legacy_key IS NULL) OR (legacy_source IS NOT NULL AND legacy_key IS NOT NULL))
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
